FAQS = {
 'accounts': [('Why do old expenses not affect an account?', 'Older unassigned expenses can be linked to the correct account later. A payment label alone does not create an account balance. Also check whether their dates are before the account’s starting balance date.'),('Why does a balance not match this month’s spending?', 'Balances are current. A month filter only changes period reports. Check the account’s opening amount/date, linked payment choices and later entries. Do not enter opening money a second time as Income.'),('What does archive do?', 'Archive hides the account from active choices while retaining history and its balance in Overall. Settle or transfer remaining money if you want a zero balance. Delete is available only for an unused account.')],
 'entries': [('How do I correct an entry?', 'Open Activity and tap the entry. Edit the amount, account, category or note, then save. Linked refunds and repayments can limit changes to shared originals; correct the linked records first.'),('Is buying for a friend an ordinary expense?', 'Use the shared-payment option and allocate your share and their share. Set yours to zero when all of the purchase belongs to the friend. Only your share counts as personal spending.')],
 'insights': [('Where do I change theme, currency or entry choices?', 'Open Settings → Preferences for System / Light / Dark, currency and defaults. Categories & payments manages your entry options. These settings do not add new money.'),('Why are the chart and net spending different?', 'Refunds reduce net personal spending. The donut uses positive category totals. Also check the period, account view and any filters.'),('Can I keep recent entries private?', 'Use Hide in Latest entries on Home. Show reveals them again. This changes the preview, not your stored transactions.')],
 'people': [('Why does a person have both receive and pay amounts?', 'You can owe someone for one item while they owe you for another. Open the correct item to settle it. The app keeps these directions separate.'),('Are splitter friends the same people?', 'No. Lena / Dena belongs to the financial ledger. Saved friends inside Split bills belong to the separate device-local tool.')],
 'split-bills': [('Does saving this bill reduce my bank balance?', 'No. The standalone splitter calculates shares and payment records. Create the appropriate ledger entry separately if you want the actual money movement recorded in Accounts.'),('Can different items have different people?', 'Yes. Select the people and portion weights for each item independently. At least one person must share each item.')],
 'split-payments': [('Why are there no reimbursement suggestions yet?', 'Check Restaurant due. Friend-to-friend suggestions appear once the restaurant is fully paid.'),('Why can I not edit the bill’s shares?', 'Undo existing friend payment records first. Restaurant payments are retained for your review. This prevents earlier settlements from being silently applied to changed shares.')],
 'receipts': [('Can I trust every recognized line?', 'No. Dates, headings and totals can be mistaken for items. Review the selection, correct amounts and explicitly confirm the tax rate.'),('What if recognition fails?', 'Try a clearer English image or scanned PDF within the size/page limits, edit the recognized text, or enter items manually.')],
 'sheets': [('Why did cleared report rows come back?', 'Transactions is rebuilt from stored sync data. Clearing report cells does not clear the financial ledger. Use the app’s deliberate history action for a fresh start; keep hidden Sync Support intact.'),('My new entries are not in the Sheet. What next?', 'Check the Web App URL ends in /exec and the current script is deployed as a new version. Test Connection, then Sync Now. A dashboard refresh alone does not send local entries.'),('Should iOS use this Android script?', 'No. The iOS Shortcut is a separate expense-to-Sheet workflow with its own template and script. Android accounts, the financial ledger and standalone splitter are not features of that Shortcut.')],
 'backups': [('Will importing my old backup remove the newest entries?', 'No. Import merges by stable ID and preserves newer local versions. It is not a complete rollback. Review the import report.'),('How do I move split bills to a new phone?', 'There is currently no restorable split-bill export or transfer in this app. Share summary gives a readable record, not a backup. Keep the original app/device if those bills are needed.')],
}
